# ---------- payload: desktop-plugins/bot-heartbeat/plugin.js ----------
mkdir -p "$PAYLOAD/desktop-plugins/bot-heartbeat"
cat > "$PAYLOAD/desktop-plugins/bot-heartbeat/plugin.js" <<'__NOETHERA_PLUGIN_EOF__'
/**
 * bot-heartbeat — shows in the Bots roster WHICH bot is working and ON WHAT.
 *
 * The stock roster only shows the canonical Bot Chat's preview + dot; work in
 * a kanban worker or in another chat tab of the same bot is invisible (and the
 * built-in "work" mood is only drawn on Geometric faces). This plugin:
 *   1. polls session.active_list every 3s — the gateway's LIVE sessions with
 *      status working / waiting / idle (authoritative for long turns, where
 *      last_activity_at can sit still for minutes),
 *   2. polls profiles.list every 5s to map those sessions to bots and to read
 *      kanban/tool worker heartbeats (workers stamp last_activity_at <= 60s),
 *   3. injects CSS: green pulsing ring on the avatar + an activity line
 *      ("⚙ Kanban · SDK-2.1.19-APIFIX …") under the row's preview,
 *   4. shows a status-bar chip "Working: …" with details on hover.
 *
 * Pure CSS on the roster's data-roster-key hook — no DOM mutation.
 * Plain ESM, loaded uncompiled. Only @hermes/plugin-sdk / react resolve.
 */

import { cn, host, Tip, useQuery } from '@hermes/plugin-sdk'
import { jsx, jsxs } from 'react/jsx-runtime'

const ID = 'bot-heartbeat'
const WORKER_WINDOW_S = 150 // workers stamp last_activity_at every <=60s
const CHAT_WINDOW_S = 90 // same "active now" window the roster uses
const PROFILES_POLL_MS = 5000
const LIVE_POLL_MS = 4000

const SOURCE_LABEL = {
  kanban: '⚙ Kanban',
  tool: '⚙ Subagent',
  cron: '⏱ Routine',
  oneshot: '✉ Pesan',
  delegate: '⚙ Subagent'
}

/** stored session id → live state, for every live session on the gateway.
 *  `bg` = running background processes (terminal background=true) that
 *  outlived the turn — the session reads "idle" but the bot is still busy. */
function liveMap(result) {
  const map = new Map()

  for (const s of Array.isArray(result?.sessions) ? result.sessions : []) {
    const status = String(s?.status || '')
    const bg = Array.isArray(s?.bg) ? s.bg : []
    const busy = status === 'working' || status === 'starting' || status === 'waiting'
    const key = String(s?.session_key || s?.id || '')

    if (key && (busy || bg.length)) {
      map.set(key, { status, bg, title: String(s.title || ''), preview: String(s.preview || '') })
    }
  }

  return map
}

/** Live sessions with running bg processes that no profile row claims by id:
 *  attribute them by the profile path in their commands
 *  (e.g. "S=~/.hermes/profiles/jarvis/cache/scratch"). */
function orphanBgByProfile(map, claimed) {
  const out = new Map()

  for (const [key, hit] of map) {
    if (claimed.has(key) || !hit.bg.length) {
      continue
    }

    for (const p of hit.bg) {
      const m = /\/profiles\/([A-Za-z0-9_-]+)\//.exec(String(p.command || ''))

      if (m && !out.has(m[1])) {
        out.set(m[1], hit)
      }
    }
  }

  return out
}

/** Live list + each live session's background processes (process.list). */
async function fetchLive() {
  const res = await host.request('session.active_list', {})
  const sessions = Array.isArray(res?.sessions) ? res.sessions : []

  await Promise.all(
    sessions.map(async s => {
      try {
        const r = await host.request('process.list', { session_id: s.id })
        s.bg = (Array.isArray(r?.processes) ? r.processes : []).filter(p => p?.status === 'running')
      } catch {
        s.bg = []
      }
    })
  )

  return { sessions }
}

const bgLine = bg => {
  const cmd = String(bg[0]?.command || '').replace(/\s+/g, ' ').trim()

  return `${bg.length} proses${cmd ? ` · ${cmd.slice(0, 80)}` : ''}`
}

function sessionIdsOf(row) {
  const ids = []
  const push = (v, title) => v && ids.push([String(v), title])

  push(row?.last_session?.id, row?.last_session?.title)
  push(row?.canonical_session?.id, 'Bot Chat')
  push(row?.canonical_session?.resolved_id, 'Bot Chat')
  push(row?.worker_session?.id, row?.worker_session?.title)

  return ids
}

function activityOf(row, now, live, orphans) {
  const canon = row?.canonical_session
  const isCanonical = id => Boolean(canon && (id === canon.id || id === canon.resolved_id))

  // 1. Live turn on the gateway — authoritative, no time window needed.
  for (const [id, fallbackTitle] of sessionIdsOf(row)) {
    const hit = live.get(id)

    if (hit && hit.status !== 'idle') {
      const waiting = hit.status === 'waiting'
      const title = hit.title || fallbackTitle || 'Chat'

      return {
        kind: waiting ? '⏸ Butuh input' : isCanonical(id) ? '💬 Bot Chat' : '💬 Chat',
        title,
        detail: hit.preview,
        waiting,
        // Bot Chat already shows its own preview in the row; only flag waiting.
        noLine: isCanonical(id) && !waiting
      }
    }
  }

  // 2. Turn ended but background processes still running.
  const bgHit =
    sessionIdsOf(row)
      .map(([id]) => live.get(id))
      .find(h => h?.bg?.length) || orphans.get(String(row?.name || ''))

  if (bgHit) {
    return { kind: '⚙ Background', title: bgLine(bgHit.bg), detail: bgHit.title }
  }

  // 2. Kanban / tool worker heartbeat.
  const w = row?.worker_session
  const wTs = Number(w?.last_active || 0)

  if (wTs && now - wTs < WORKER_WINDOW_S) {
    return {
      kind: SOURCE_LABEL[String(w.source || '').toLowerCase()] || '⚙ Worker',
      title: String(w.title || ''),
      detail: `heartbeat ${Math.round(now - wTs)}s ago`
    }
  }

  // 3. Fallback: something written very recently (e.g. another machine).
  const s = row?.last_session
  const sTs = Number(s?.last_active || 0)

  if (s && sTs && now - sTs < CHAT_WINDOW_S) {
    return {
      kind: isCanonical(s.id) ? '💬 Bot Chat' : '💬 Chat',
      title: String(s.title || 'Chat'),
      detail: `${Math.round(now - sTs)}s ago`,
      noLine: isCanonical(s.id)
    }
  }

  return null
}

function workingBots(profiles, live) {
  const rows = Array.isArray(profiles?.profiles) ? profiles.profiles : []
  const now = Date.now() / 1000
  const map = liveMap(live)
  const claimed = new Set(rows.flatMap(row => sessionIdsOf(row).map(([id]) => id)))
  const orphans = orphanBgByProfile(map, claimed)

  return rows
    .map(row => {
      const act = activityOf(row, now, map, orphans)

      return act
        ? { name: String(row.name || 'default'), label: String(row.display_name || row.name || 'default'), ...act }
        : null
    })
    .filter(Boolean)
}

// CSS string literal: escape backslashes, quotes and newlines.
const cssString = s => `"${String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\r\n]+/g, ' ')}"`
const cssAttr = s => (globalThis.CSS?.escape ? CSS.escape(s) : String(s).replace(/["\\]/g, '\\$&'))
const rowSel = name => `[data-roster-key$="::${cssAttr(name)}"]`
const list = (bots, suffix) => bots.map(b => `${rowSel(b.name)}${suffix}`).join(',\n') || '.hb-none'

function cssFor(bots) {
  if (!bots.length) {
    return ''
  }

  const working = bots.filter(b => !b.waiting)
  const waiting = bots.filter(b => b.waiting)
  const withLine = bots.filter(b => !b.noLine)

  return `
:root { --hb-green: var(--ui-success, #10b981); --hb-amber: #f59e0b; }
@keyframes hb-bot-pulse {
  0%   { box-shadow: 0 0 0 0 color-mix(in srgb, var(--hb-ring) 75%, transparent); }
  70%  { box-shadow: 0 0 0 6px color-mix(in srgb, var(--hb-ring) 0%, transparent); }
  100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--hb-ring) 0%, transparent); }
}
@keyframes hb-bot-dot { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
${list(working, ' > div:first-child')} { --hb-ring: var(--hb-green); }
${list(waiting, ' > div:first-child')} { --hb-ring: var(--hb-amber); }
${list(bots, ' > div:first-child')} {
  position: relative;
  outline: 2px solid var(--hb-ring);
  outline-offset: -2px;
  animation: hb-bot-pulse 1.6s ease-out infinite;
}
${list(bots, ' > div:first-child::after')} {
  content: '';
  position: absolute;
  right: -2px;
  bottom: -2px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--hb-ring);
  border: 2px solid var(--ui-sidebar-background, var(--background, transparent));
  animation: hb-bot-dot 1.2s ease-in-out infinite;
}
${list(withLine, ' > div.min-w-0::after')} {
  display: block;
  margin-top: 2px;
  font-size: 0.6875rem;
  line-height: 1rem;
  color: var(--hb-green);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
${list(waiting.filter(b => !b.noLine), ' > div.min-w-0::after')} { color: var(--hb-amber); }
/* Active row: the activity line replaces the preview — keep the row 2 lines. */
${list(withLine, ' > div.min-w-0 > div:nth-child(2)')} { display: none !important; }
${withLine.map(b => `${rowSel(b.name)} > div.min-w-0::after { content: ${cssString(`${b.kind} · ${b.title}`)}; }`).join('\n')}
@media (prefers-reduced-motion: reduce) {
  ${list(bots, ' > div:first-child')} { animation: none; }
}
`
}

function HeartbeatChip() {
  const profiles = useQuery({
    queryKey: ['plugin', ID, 'profiles'],
    queryFn: () => host.request('profiles.list', {}),
    refetchInterval: PROFILES_POLL_MS,
    refetchIntervalInBackground: true,
    staleTime: 0
  })

  const live = useQuery({
    queryKey: ['plugin', ID, 'live'],
    queryFn: fetchLive,
    refetchInterval: LIVE_POLL_MS,
    refetchIntervalInBackground: true,
    staleTime: 0,
    retry: false
  })

  const bots = workingBots(profiles.data, live.data)
  const tip = bots
    .map(b => `${b.label} — ${b.kind}: ${b.title}${b.detail ? `\n   ${b.detail.slice(0, 120)}` : ''}`)
    .join('\n')

  return jsxs('span', {
    className: 'inline-flex h-full items-center',
    children: [
      jsx('style', { children: cssFor(bots) }),
      bots.length
        ? jsx(Tip, {
            label: jsx('span', { style: { whiteSpace: 'pre-line' }, children: tip }),
            children: jsxs('span', {
              className: cn(
                'inline-flex h-full items-center gap-1.5 px-1.5 text-[0.6875rem]',
                'text-(--ui-text-secondary)'
              ),
              children: [
                jsx('span', {
                  style: {
                    width: 7,
                    height: 7,
                    borderRadius: '50%',
                    background: 'var(--hb-green)',
                    animation: 'hb-bot-dot 1.2s ease-in-out infinite'
                  }
                }),
                `Working: ${bots.map(b => b.label).join(', ')}`
              ]
            })
          })
        : null
    ]
  })
}

// Always-on: shrink every roster avatar inside its 34px slot so the pulse
// ring (drawn on the slot) has clear space around it, and equalise sizes:
// photos/geometric faces fill ~90–100% of the slot, blob faces only ~64%.
// Targets ≈ 25–26px for all of them.
const SIZE_CSS = `
[data-roster-key] > div:first-child {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 26%;
}
[data-roster-key] > div:first-child img {
  transform: scale(0.76);
}
[data-roster-key] > div:first-child svg[data-bot-face]:not([viewBox="0 0 100 100"]) {
  transform: scale(0.8);
}
[data-roster-key] > div:first-child svg[data-bot-face][viewBox="0 0 100 100"] {
  transform: scale(1.15);
  overflow: visible;
}
`

function mountSizeStyle() {
  const id = 'hermes-plugin-bot-heartbeat-size'
  document.getElementById(id)?.remove()
  const el = document.createElement('style')
  el.id = id
  el.textContent = SIZE_CSS
  document.head.appendChild(el)

  return () => el.remove()
}

export default {
  id: ID,
  name: 'Bot Heartbeat',
  register(ctx) {
    ctx.onDispose?.(mountSizeStyle())
    ctx.register({
      id: 'chip',
      area: 'statusBar.right',
      order: 120,
      render: () => jsx(HeartbeatChip, {})
    })
  }
}
__NOETHERA_PLUGIN_EOF__

# ---------- payload: desktop-plugins/composer-tidy/plugin.js ----------
mkdir -p "$PAYLOAD/desktop-plugins/composer-tidy"
cat > "$PAYLOAD/desktop-plugins/composer-tidy/plugin.js" <<'__NOETHERA_PLUGIN_EOF__'
/**
 * composer-tidy — keeps the stock fused look of the composer status stack
 * ("1 Background", todos, subagents, queue) but stops its last row from
 * running into the composer seam and the collapse grip parked on it.
 *
 * Core draws the stack as the top half of one capsule with no bottom padding,
 * so the final row sits right on the seam where the grip (top: -0.5rem)
 * overlaps it. This only adds clearance under the content.
 *
 * Pure CSS on stable data-slot hooks. Disable in Settings → Plugins (or
 * delete the folder) to get the stock spacing back.
 */

const ID = 'composer-tidy'
const STYLE_ID = 'hermes-plugin-composer-tidy'

const CSS = `
/* Top: breathing room under the card's rounded top edge.
   Bottom: clear the seam + the 6px grip that sits 8px above it. */
[data-slot='composer-status-stack'] [data-slot='status-stack-content'] {
  padding-top: 6px;
  padding-bottom: 12px;
}
`

function mountStyle() {
  document.getElementById(STYLE_ID)?.remove()
  const el = document.createElement('style')
  el.id = STYLE_ID
  el.textContent = CSS
  document.head.appendChild(el)

  return () => el.remove()
}

export default {
  id: ID,
  name: 'Composer Tidy',
  register(ctx) {
    const dispose = mountStyle()

    ctx.onDispose?.(dispose)
  }
}
__NOETHERA_PLUGIN_EOF__

[ -f "$PAYLOAD/themes/$SKIN.yaml" ] || { echo "Unknown skin '$SKIN' (available: $(ls "$PAYLOAD/themes" | sed 's/\.yaml$//' | tr '\n' ' '))" >&2; exit 2; }

# 1. Skins into the root and every profile (the desktop reads the active profile's home).
build() { cat "$1"; printf '\ncustomCSS: |\n'; sed 's/^/  /' "$PAYLOAD/bubbles.css"; }
stamp="$(date +%Y%m%d-%H%M%S)"
homes=("$ROOT")
for p in "$ROOT"/profiles/*/; do [ -d "$p" ] && homes+=("${p%/}"); done
for home in "${homes[@]}"; do
  mkdir -p "$home/skins"
  for theme in "$PAYLOAD"/themes/*.yaml; do
    name="$(basename "$theme")"; target="$home/skins/$name"
    build "$theme" > "$PAYLOAD/built.yaml"
    if [ -f "$target" ] && ! cmp -s "$PAYLOAD/built.yaml" "$target"; then
      mkdir -p "$home/skins/.backup"; cp "$target" "$home/skins/.backup/$name.$stamp"
    fi
    cp "$PAYLOAD/built.yaml" "$target"; chmod 644 "$target"
  done
  rm -f "$home/skins/noethera.yaml"
done
echo "Skins installed in ${#homes[@]} Hermes home(s): $ROOT and $(( ${#homes[@]} - 1 )) profile(s)"

# 2. Activate the skin everywhere (hermes config set writes valid YAML; never hand-edit config.yaml).
for home in "${homes[@]}"; do
  [ -f "$home/config.yaml" ] || continue
  HERMES_HOME="$home" hermes config set display.skin "$SKIN" >/dev/null 2>&1 \
    && echo "  display.skin = $SKIN  ($home)" || echo "  Could not set the skin in $home; run: HERMES_HOME=$home hermes config set display.skin $SKIN"
done

# 3. Open Sans (bubbles.css uses the installed font, not the network).
if [ "$DO_FONT" = 1 ]; then
  case "$(uname -s)" in
    Darwin) fontdir="$HOME/Library/Fonts"; have() { compgen -G "$HOME/Library/Fonts/OpenSans*" >/dev/null || compgen -G "/Library/Fonts/OpenSans*" >/dev/null; } ;;
    *)      fontdir="$HOME/.local/share/fonts"; have() { fc-list 2>/dev/null | grep -qi "Open Sans"; } ;;
  esac
  if have; then
    echo "Open Sans already installed"
  elif [ "$(uname -s)" = Darwin ] && command -v brew >/dev/null 2>&1 && brew install --cask font-open-sans >/dev/null 2>&1; then
    echo "Open Sans installed (Homebrew)"
  else
    mkdir -p "$fontdir"
    base="https://github.com/google/fonts/raw/main/ofl/opensans"
    if curl -fsSL "$base/OpenSans%5Bwdth,wght%5D.ttf" -o "$fontdir/OpenSans[wdth,wght].ttf" \
       && curl -fsSL "$base/OpenSans-Italic%5Bwdth,wght%5D.ttf" -o "$fontdir/OpenSans-Italic[wdth,wght].ttf"; then
      command -v fc-cache >/dev/null 2>&1 && fc-cache -f "$fontdir" >/dev/null 2>&1 || true
      echo "Open Sans installed (Google Fonts) in $fontdir"
    else
      echo "Note: could not install Open Sans; the app falls back to the system font. Install it manually later."
    fi
  fi
fi

# 4. Desktop glass sidebar (stored by the app, not in the skin).
if [ "$DO_DESKTOP" = 1 ]; then
  case "$(uname -s)" in
    Darwin) appdir="${NOETHERA_APP_DIR:-$HOME/Library/Application Support/Hermes}" ;;
    *)      appdir="${NOETHERA_APP_DIR:-${XDG_CONFIG_HOME:-$HOME/.config}/Hermes}" ;;
  esac
  mkdir -p "$appdir"
  cat > "$appdir/translucency.json" <<'JSON'
{
  "intensity": 29,
  "fade": 0,
  "mode": "glass",
  "material": "header",
  "scope": "sidebar"
}
JSON
  echo "Desktop translucency set (glass sidebar)"
fi

# 5. Desktop plugins (app-level: the desktop loads them from the ROOT home only).
if [ "$DO_PLUGINS" = 1 ]; then
  for dir in "$PAYLOAD"/desktop-plugins/*/; do
    id="$(basename "$dir")"; target="$ROOT/desktop-plugins/$id/plugin.js"
    mkdir -p "$ROOT/desktop-plugins/$id"
    if [ -f "$target" ] && ! cmp -s "$dir/plugin.js" "$target"; then
      mkdir -p "$ROOT/desktop-plugins/.backup"; cp "$target" "$ROOT/desktop-plugins/.backup/$id.$stamp.js"
    fi
    cp "$dir/plugin.js" "$target"; chmod 644 "$target"
  done
  echo "Desktop plugins installed: $(ls "$PAYLOAD/desktop-plugins" | tr '\n' ' ')(enable in Settings > Plugins if off)"
fi

echo
echo "Done. Quit and reopen the Hermes desktop app (Cmd+Q) to load the fonts, sidebar and plugins; the CLI/TUI repaint live."
echo "New profile later? Run this script again. Revert: hermes config set display.skin default"
